#!/usr/bin/env bun
/**
 * Regenerates `e2e/sensitive-values.txt` from the test project's fixtures
 * (`pasteguard-test/fixtures/clients.txt`, `env.fake`). Deterministic
 * extraction via targeted regexes (one per PII/secret type known to the
 * engine, cf. `integrations/claude-code/README.md`), no dependency on the
 * detector.
 *
 * The generated file is the ONLY one used by `run.ts` for the anti-leak
 * grep: it is committed and serves as a stable reference. Rerun this
 * script after any change to the fixtures:
 *
 *   bun run integrations/claude-code/e2e/build-sensitive-values.ts
 */
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

const TEST_PROJECT_DIR =
  process.env.PASTEGUARD_E2E_PROJECT_DIR ?? "/Users/jb/Documents/MyProjects/LOCAL/pasteguard-test";
const FIXTURES = ["fixtures/clients.txt", "fixtures/env.fake"];
const OUTPUT_FILE = join(import.meta.dir, "sensitive-values.txt");
const MIN_LENGTH = 6;

/** One regex per recognized type (PII and secrets, cf. README) + a generic fallback. */
const GLOBAL_PATTERNS: RegExp[] = [
  // EMAIL_ADDRESS
  /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,
  // IP_ADDRESS
  /\b\d{1,3}(?:\.\d{1,3}){3}\b/g,
  // IBAN_CODE (spaced groups)
  /\bFR\d{2}(?:\s?[0-9A-Z]{4}){2,7}\s?[0-9A-Z]{1,4}\b/g,
  // VAT_CODE (FR + 11 digits glued together, no space)
  /\bFR\d{2}\d{9}\b/g,
  // PHONE_NUMBER (FR formats: +33 7 98 76 54 32 / 06 12 34 56 78)
  /\+33[\s.]?\d(?:[\s.]?\d{2}){4}\b|\b0\d(?:[\s.]?\d{2}){4}\b/g,
  // API_KEY_SK
  /\bsk-ant-[A-Za-z0-9-]+/g,
  // API_KEY_GITHUB
  /\bghp_[A-Za-z0-9]+/g,
  // CONNECTION_STRING
  /\b\w+:\/\/\S+/g,
  // JWT_TOKEN
  /\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g,
  // PERSON (two or more words with an initial capital, hyphens allowed within a word)
  /\b[A-ZÀ-Ý][a-zà-ÿ]+(?:-[A-ZÀ-Ý][a-zà-ÿ]+)?(?:\s[A-ZÀ-Ý][a-zà-ÿ]+(?:-[A-ZÀ-Ý][a-zà-ÿ]+)?)+\b/g,
  // LOCATION (FR postal code + city)
  /\b\d{5}\s[A-ZÀ-Ý][a-zà-ÿ]+\b/g,
];

/** `Label: value` lines (clients.txt): captures everything after the first `:`. */
const LABEL_COLON_LINE = /^[^:#=]{1,40}:\s*(.+)$/;
/** `KEY=value` lines (env.fake): captures everything after the first `=`. */
const ENV_KEY_VALUE_LINE = /^[A-Z][A-Z0-9_]*=(.+)$/;

function extractFromText(text: string): string[] {
  const values: string[] = [];
  for (const pattern of GLOBAL_PATTERNS) {
    for (const match of text.matchAll(pattern)) values.push(match[0]);
  }
  for (const rawLine of text.split("\n")) {
    const line = rawLine.trim();
    if (line.length === 0) continue;
    const labelMatch = line.match(LABEL_COLON_LINE);
    if (labelMatch?.[1]) values.push(labelMatch[1].trim());
    const envMatch = line.match(ENV_KEY_VALUE_LINE);
    if (envMatch?.[1]) values.push(envMatch[1].trim());
  }
  return values;
}

async function main(): Promise<void> {
  const allValues: string[] = [];
  for (const relPath of FIXTURES) {
    const absPath = join(TEST_PROJECT_DIR, relPath);
    const text = await readFile(absPath, "utf8");
    allValues.push(...extractFromText(text));
  }

  const deduped = [...new Set(allValues.map((v) => v.trim()))]
    .filter((v) => v.length >= MIN_LENGTH)
    .sort((a, b) => a.localeCompare(b));

  const header =
    `# Generated by build-sensitive-values.ts from ${FIXTURES.join(", ")}, do not edit by hand.\n` +
    `# One value per line, duplicates removed, lines shorter than ${MIN_LENGTH} characters ignored.\n`;
  await writeFile(OUTPUT_FILE, `${header}${deduped.join("\n")}\n`, "utf8");

  console.log(`${deduped.length} sensitive value(s) written to ${OUTPUT_FILE}`);
  for (const v of deduped) console.log(`  - ${v}`);
}

await main();
